insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 1, 'This module carries several sizing routes and exactly one of them works out its own relief load. Which one, and from what?', '["The gas and vapour route, from the vessel inventory and the relieving pressure it is handed.", "The knockout drum route, from the vapour rate the flare header carries.", "The API 521 fire case, from vessel geometry together with a drainage answer and an environment factor the caller states.", "The steam route, because the Napier correction fixes the load as soon as the relieving pressure and the superheat factor are both known."]'::jsonb, 2, 'Every other sizing route in the module takes a relief load as an input and returns the area that load demands. The fire case starts one step earlier, at a wetted area.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 2, 'A caller hands the gas route a relief load that belongs to the wrong scenario. What does the route do?', '["It returns the area that load demands at the stated relieving pressure, without hesitating.", "It refuses, because a load outside the range of the stated vessel geometry cannot be sized.", "It returns the area with a warning that the load and the pressure disagree.", "It substitutes the fire load it computes from the same conditions and sizes on the larger of the two."]'::jsonb, 0, 'Which scenario governs is not the question the route was asked. The engine never chooses the case, and an area is only ever correct for the load it was given.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 3, 'Read as an object rather than as a set of answers, how does this module''s export surface divide?', '["22 exports in all: 12 of them returning a bare number, 7 returning an object, 2 published tables and 1 derived constant.", "22 exports in all: 7 returning a bare number, 12 returning an object, 1 published table and 2 derived constants of its own.", "14 exports in all, one for each standard orifice the selection route can return.", "22 exports in all: 7 returning a bare number, 12 returning an object, 2 published tables and 1 derived constant."]'::jsonb, 3, 'The counts come from reading the module rather than from a list in a comment, and the return kinds come from asking what each export actually gives back.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 4, 'One of the seven bare-number exports is handed an input it cannot work with. How does it say so?', '["It returns zero, which is the only value outside the range any of them can legitimately produce.", "It returns NaN, because a bare number has no field to put an error message in.", "It returns an object carrying an error string, which is the contract every export in the module keeps.", "It throws, and the caller is expected to catch it."]'::jsonb, 1, 'The object routes have somewhere to put a message and use it. The bare-number routes have nowhere, so the refusal is the value itself.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 5, 'What is the contract every object-returning route in this module keeps?', '["Either a finite result, or a result with every numeric field set to zero.", "Either a finite result, or an object carrying an error string.", "Either a finite result carrying its own warning slot, or nothing at all.", "Either a finite result, or the nearest result the route could reach with a note saying how far it fell short."]'::jsonb, 1, 'A non-finite number arriving with no error key is exactly what a caller''s error check cannot see, so the module is built never to produce one.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 6, 'Why does a guard written as a check on the error key depend on that contract holding?', '["Because the error key is the only field a caller may read before the route converges.", "Because the error key carries the input that caused the refusal, which the guard retries on.", "Because a warning and an error share one field, so the guard has to read both meanings out of it.", "Because a route that returned a non-finite number with no error key would slip straight past it."]'::jsonb, 3, 'The guard can only see what the contract promises to put in front of it. That is why both halves of the contract are checked rather than assumed.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 7, 'A blocked-in outlet and thermal expansion in a liquid-packed line are two of the commonest relieving cases on a plant. How does this module size them?', '["Somebody works the load out elsewhere and types it in, and the module returns the area that load demands.", "Both have their own routes, and each computes a load from the process conditions it is given.", "Both are sized through the fire case, with the blocked-in duty standing in for a pool fire duty.", "Neither can be sized here at all, because the module refuses a load it did not compute itself."]'::jsonb, 0, 'Both cases ask what the process was doing, and no route here is told that. The fire case is the exception because everything it needs is geometry and two stated answers.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 8, 'A relief load is written down for later use. Which three qualities does it have to carry to still be usable?', '["A rate, at operating conditions, with the orifice letter it was found to need.", "A rate, an area and a margin, so the selection can be reproduced.", "A rate, at relieving conditions, for one named scenario.", "A rate, at relieving conditions, with the certified discharge coefficient of the valve it was sized for."]'::jsonb, 2, 'The scenario name is the quality that goes missing. A load without it looks like any other load, and the studio will size against it cheerfully.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 9, 'The knockout drum route is handed a vapour rate in standard cubic feet a day where it wanted actual cubic feet a second. What happens?', '["It refuses, because a rate that large cannot be a volumetric rate at drum conditions.", "It converts the rate itself, using the header pressure it was given alongside the diameter.", "It returns a length and a note saying the rate looks like a standard rate rather than an actual one.", "It sizes a drum for the number it was given, because the two quantities are indistinguishable once they are in the box."]'::jsonb, 3, 'The route is never told what pressure the header runs at, so it cannot convert anything, and a positive number in one unit looks exactly like a positive number in the other.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 10, 'The teaching drum''s vapour density of 0.124385 lb/ft3 is not one of the figures stated about it. Where does it come from?', '["It is stated alongside the liquid density of 36.500000 lb/ft3, since the drum route needs both.", "It is derived from the stated gas gravity with the package''s own gas constant and air molecular weight.", "It is returned by the drum route from the diameter and the holdup fraction it was given.", "It is read from the vapour viscosity of 0.013500 cp at the stated temperature of 160.000000 degF."]'::jsonb, 1, 'The stated facts are a rate, a pressure, a temperature, a gas gravity, a liquid density and a vapour viscosity. The density is worked out from the third and fourth of those.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 11, 'The stated rate of 44.000000 MMscfd becomes an actual vapour rate of 212.481739 ft3/s. What standard base does that conversion use?', '["14.696 psia and 519.67 degR, which is the package''s own base.", "42.000000 psia and 160.000000 degF.", "14.700000000000 psia and 519.67 degR, the atmospheric constant the sizing routes share.", "The base is not fixed, since the conversion is performed from whatever pressure and temperature the caller states."]'::jsonb, 0, 'A standard cubic foot is a bookkeeping unit defined at a reference pressure and temperature, and more than one reference is in common use. Naming the base is half the conversion.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 12, 'A standard rate is typed into the box that wants the actual one, on a header running above the standard base. Which way does the answer move?', '["The drum is sized for less gas than the header is actually carrying.", "The drum length is unaffected, because the route works on the ratio of the rate to the vapour area.", "The drum is sized for more gas than the header is carrying.", "The drum length is unaffected, because the holdup fraction rescales the rate before the transit time is formed."]'::jsonb, 2, 'Compress a gas and the same molecules occupy less volume, so the actual volumetric rate is the smaller figure. Asking for the larger one asks for a drum the header does not need.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 13, 'Which four things does this tier say the engine leaves to the caller?', '["The wetted height truncation, the choice of governing case, the orifice letter the required area lands on, and the margin printed beside that letter on the selection row.", "The wetted height truncation, the choice of governing case, the conversion from a standard rate to an actual one, and the fluid properties at drum conditions.", "The environment factor, the latent heat, the drainage answer and the level, since all four are typed.", "The relieving pressure, the critical pressure ratio, the settling velocity and the vapour density."]'::jsonb, 1, 'Each of the four is a place where a perfectly correct engine answer can be the wrong answer to your question. None of them is a defect, and the module states all four.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 14, 'Why can the wetted-area route not apply the 25 ft height limit itself?', '["It is never told the latent heat of the boiling liquid.", "It is never told the orientation of the vessel.", "It could apply the limit, and it does, which is why a level above 25 ft returns the same area as a level at it.", "It is never told where grade is, and the limit is measured above grade."]'::jsonb, 3, 'A vessel on a plinth, one on a platform two decks up and one in a bunded pit can carry the same level and present completely different amounts of shell within reach. The limit arrives as a note on every duty instead.'),
  ('relief', 'intermediate', 'module', 'm01-where-the-relief-load-comes-from', 15, 'Of the figures this module handles, which set is typed rather than computed?', '["The bellows factors Kb and Kw, the superheat factor KSH, and the API 526 orifice table.", "The critical ratio, F2, the viscosity correction and Napier.", "The circular segment, the terminal velocity balance and the march.", "The environment factor, the drainage answer and the liquid level."]'::jsonb, 0, 'What the module can derive in closed form it derives. What is published as a chart or a table enters as an input with its reference named, and a typed factor is a number somebody read off a curve.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 1, 'A horizontal vessel is wetted to a level. What is the wetted area the fire case starts from?', '["The plan area of the liquid surface, multiplied by the length of the vessel.", "The wetted arc round the circular segment, multiplied by the length of the vessel.", "The circumference of the vessel, multiplied by the liquid level.", "The lateral surface of the vessel, multiplied by the level as a fraction of the diameter."]'::jsonb, 1, 'That expression is exact and carries no correlation in it, which makes the first link of the fire chain the one place an answer can be right beyond argument.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 2, 'Stand the same vessel on end. What is the wetted area then?', '["The circular segment, multiplied by the wetted height.", "The circumference, multiplied by the level as a fraction of the diameter.", "The plan area of the vessel, multiplied by the wetted height.", "The circumference, multiplied by the wetted height."]'::jsonb, 3, 'There is no segment and no arc angle in the vertical branch. The liquid touches the shell round one circle and the wetted surface is the band from the bottom tangent up to the level.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 3, 'The teaching vessel is 12.000000 ft across and 45.000000 ft long at a level of 4.200000 ft. What does it return in each orientation?', '["683.6960 ft2 lying down and 158.3363 ft2 standing up.", "683.6960 ft2 lying down and 226.1947 ft2 standing up.", "848.2300 ft2 lying down and 158.3363 ft2 standing up.", "683.6960 ft2 in either orientation, since the level and the steel are the same."]'::jsonb, 0, 'The printed ratio between the two readings is 4.317999814064. They are two exact answers to two different questions, and the orientation field is where the question is named.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 4, 'At a level of exactly 6.000000 ft that vessel returns 848.2300 ft2. What else equals that figure?', '["The whole lateral surface of the cylinder, at a ratio of 1.000000000000.", "The vertical reading at that same level, which the sweep also gives as 848.2300 ft2.", "Half the lateral surface of the cylinder, to a printed ratio of 1.000000000000.", "Twice the area at a level of 2.400000 ft, which is 500.7394 ft2."]'::jsonb, 2, 'Half full is the one level on a horizontal vessel with an answer anybody can reach without the segment: a diameter, a length and pi.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 5, 'Why is exact agreement at half full a poor gate on the geometry, however useful it is as a sanity check?', '["Any geometry that is wrong away from half full can still be exactly right there.", "The agreement is only exact to six decimals, which is too coarse to separate two candidate expressions.", "The half-full case is the only level the published set does not carry, so nothing independent confirms it.", "A ratio of 1.000000000000 is printed rather than computed, so it cannot fail whatever the geometry does."]'::jsonb, 0, 'One point of agreement between two expressions is a single equation, and a great many wrong expressions satisfy any single equation you care to write down. Ask what wrong answer a check would have caught.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 6, 'The level sweep on the teaching vessel ends at 12.000000 ft with an area of 1696.4600 ft2. What is that figure?', '["The whole surface of the cylinder including both heads, since a full vessel is fully engulfed.", "The whole lateral surface of the cylinder, since the level is clamped at the diameter.", "The largest area the route will return before it refuses a level past the diameter.", "The area at the top of the published range, above which the route returns a note instead."]'::jsonb, 1, 'A level above the diameter returns the same figure, because the shell cannot be more than fully wetted. Two levels on this vessel have closed-form answers, at the middle and at the top.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 7, 'What does the wetted-area route do about the vessel heads?', '["It adds them on the horizontal branch and ignores them on the vertical one.", "It adds a dished-end allowance proportional to the level as a fraction of the diameter.", "It ignores them, which is standard screening practice and optimistic for the shell term.", "It ignores them, which is standard screening practice and conservative for the shell term."]'::jsonb, 3, 'A wetted head would add area and therefore duty, so leaving it out cannot make the duty look smaller than the shell alone deserves. A head allowance for a detailed case is made outside this route.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 8, 'A call arrives with an orientation string the route does not recognise. What comes back?', '["The horizontal reading, since that is the orientation most vessels in a pool fire have.", "An area of zero, which the duty route then refuses in its turn.", "A refusal naming the two orientations it accepts, and no area at all.", "A refusal, and a string differing only by a capital letter is refused in the same way."]'::jsonb, 2, 'The match is case insensitive and trimmed, so a capital letter or a stray space still resolves. A silent default would hand a vertical tower a horizontal segment area and nothing on the screen would say so.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 9, 'The published wetted-area set carries 7 rows and 3 of them are vertical. Why does that matter?', '["The vertical rows are the only ones with a relative difference small enough to be meaningful.", "The vertical branch has its own derived oracle route, so a defect in one orientation cannot hide behind the other.", "Three rows is the smallest number from which the arc expression can be recovered by fitting.", "The vertical rows are the only ones the fire chain is ever run on, so they carry all the weight."]'::jsonb, 1, 'A published set exercising only horizontal geometry would pass a module with the vertical branch entirely wrong, and would report a clean run while doing it.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 10, 'One published row is a vertical vessel 8.000000 ft across and 30.000000 ft long at a level of 0.000000 ft. What is unusual about how it is reported?', '["Its relative difference is reported as unavailable rather than as zero.", "Its engine area is reported as unavailable, because an empty vessel has no wetted geometry.", "It is the only row in the set whose published and engine figures differ.", "It carries no orientation, because an empty vessel is the same in both."]'::jsonb, 0, 'A relative difference against a published zero has nothing to divide by. A tolerance that cannot be computed is reported as absent instead of as a pass, which is a small piece of honesty worth copying.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 11, 'Which published row shows that a level above the vessel diameter is ordinary on the vertical branch?', '["A vessel 8.000000 ft across and 24.000000 ft long wetted to 7.900000 ft, which returns 560.1633 ft2.", "A vessel 12.000000 ft across and 30.000000 ft long wetted to 1.200000 ft, which returns 231.6604 ft2.", "A vessel 10.000000 ft across and 40.000000 ft long wetted to 5.000000 ft, which returns 628.3185 ft2.", "A vessel 10.000000 ft across and 40.000000 ft long wetted to 12.000000 ft, which returns 376.9911 ft2."]'::jsonb, 3, 'A vertical vessel is wetted up its height, so the same level figure means different things in the two branches. On a horizontal vessel a level above the diameter is a signal that something is wrong.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 12, 'Which published row sits on the height limit this course names?', '["The 10.000000 ft tower wetted to 25.000000 ft, at 471.2389 ft2.", "The 8.000000 ft horizontal vessel wetted to 7.900000 ft, at 560.1633 ft2.", "The 6.000000 ft tower wetted to 25.000000 ft, at 471.2389 ft2.", "The 6.000000 ft tower wetted to 12.000000 ft, at 376.9911 ft2."]'::jsonb, 2, 'That row is the whole tower wetted and it is also the largest height the set exercises. A caller with a taller tower is past the limit and has to trim before the call.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 13, 'Read the horizontal over vertical column of the level sweep from the lowest level downward. What does it do?', '["It falls the whole way, from 10.767472 at the lowest level to 3.750000 at the top.", "It rises the whole way, because a standing vessel gains area faster than a lying one.", "It holds at 3.750000 from half full upward, since both readings are then linear in the level.", "It falls steeply, flattens, and then turns and rises again before the top."]'::jsonb, 3, 'The gap between the two readings is widest at a low level, because a lying vessel wets a broad band of shell for very little liquid while a standing one wets only a thin ring.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 14, 'The engine attaches a note about the height limit to something. What, and how often?', '["To every pool fire duty it returns.", "To every wetted area it returns, since that is where the level enters.", "To the duties it computes above 25 ft of wetted height only.", "To the vertical readings only, since a horizontal vessel rarely reaches the limit."]'::jsonb, 0, 'The note asks the caller to truncate the level before calling, and it is present on every duty rather than only on the ones the engine suspects. It cannot decide which those are, because it is never told where grade is.'),
  ('relief', 'intermediate', 'module', 'm02-the-wetted-area', 15, 'The relative differences on the published wetted-area rows run from 1.990e-15 to 1.186e-13. What does a spread that size say?', '["That the published figures were rounded on the way into print, like the fire duty rows.", "That the disagreement is the rounding of a double rather than anything about the geometry.", "That the arc expression and the oracle agree only to the precision the published areas carry.", "That the vertical rows agree more closely than the horizontal ones, which is the point of carrying both."]'::jsonb, 1, 'The oracle walks a polyline round the real circle and extrapolates rather than evaluating the same arc formula the engine uses, so the agreement is between two derivations and not one restated twice.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 1, 'What shape does the API 521 pool fire duty have in this engine?', '["A constant, times an environment factor, times the wetted area raised to a published exponent.", "A constant, times the wetted area, divided by the environment factor.", "A constant, times an environment factor, times the wetted area, all raised to a published exponent.", "A constant, times the wetted area raised to a published exponent, with the environment factor applied to the relief load afterwards."]'::jsonb, 0, 'Three inputs and two published figures. Which of the two constants applies is decided by a single answer about the plot.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 2, 'Which single answer decides which of the two pool fire constants the duty uses?', '["Whether the vessel is insulated to a rated fire standard.", "Whether the vessel is read lying down or standing up.", "Whether the plot has adequate drainage and firefighting.", "Whether the wetted height reaches the limit the note names."]'::jsonb, 2, 'Insulation and the other credits arrive separately as the environment factor. Drainage and firefighting are the one input that switches the constant itself.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 3, 'What are the two pool fire constants this engine carries?', '["21000.000000000000 Btu/hr without drainage and 34500.000000000000 Btu/hr with it.", "21000.000000000000 Btu/hr with drainage and 34500.000000000000 Btu/hr without.", "21000.000000000000 Btu/hr with drainage and 34500.000000000000 Btu/hr where the vessel is insulated.", "34500.000000000000 Btu/hr in both cases, with drainage entering through the environment factor."]'::jsonb, 1, 'Both are quoted at a wetted area of 1 ft2 and an environment factor of 1, which is the condition under which the constant is the whole answer.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 4, 'How were those two constants recovered from an engine that does not export them?', '["By dividing two duties at the same area and reading the constant off the quotient.", "By fitting the duty against the wetted area across the whole sweep and reading the intercept.", "By taking them from the published standard, since no question put to the engine can isolate a constant.", "By asking for a duty at a wetted area of 1 ft2 and an environment factor of 1, then repeating it with the drainage answer flipped."]'::jsonb, 3, 'At a wetted area of one the area term is one whatever the exponent happens to be, so the answer is the constant alone. That is what makes it a measurement rather than a transcription.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 5, 'What is the factor between the two pool fire constants, and how is it known?', '["1.642857142857, computed as the ratio of the two measured constants.", "1.642857142857, typed into the course from the same page the constants came from.", "0.820000000000, which is the published exponent carried through the ratio.", "It is not a figure this course carries, because a ratio between two published constants is the reader''s own invention."]'::jsonb, 0, 'The two constants are measured by calling the engine, and their ratio follows from them. A ratio somebody computed reads exactly like one nobody did, which is why this one is printed.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 6, 'The pool fire exponent is 0.820000000000. What question recovered it?', '["The quotient of two duties at 100 and 1000 ft2, over the quotient of those areas.", "The slope of the duty plotted against the wetted area, at a fixed environment factor and a fixed drainage answer.", "The log ratio of two duties at 100 and 1000 ft2, over the log ratio of those areas.", "The ratio of the duty per ft2 at 50.0000 ft2 to the duty per ft2 at 5000.0000 ft2."]'::jsonb, 2, 'The leading constant never enters that expression, which is what makes it a measurement of the exponent rather than a rearrangement of a duty.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 7, 'The duty per ft2 runs from 10384.9568 Btu/hr at 50.0000 ft2 down to 4533.1981 Btu/hr at 5000.0000 ft2. Why?', '["Because the environment factor falls as a vessel gets larger.", "Because the constant with drainage applies to the larger areas and the one without applies to the smaller.", "Because the larger areas in the sweep are vertical readings and the smaller ones horizontal.", "Because the exponent is below one, so total duty grows more slowly than the area does."]'::jsonb, 3, 'Every row in that sweep holds the environment factor and the drainage answer fixed, so the only thing moving is the area under its published power.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 8, 'What physical detail is the exponent standing in for, given what the relation does not carry?', '["That a large vessel loses more heat to its surroundings, since the relation has no ambient temperature in it.", "That a large vessel is not uniformly engulfed, since the relation has no flame height, pool extent or wind in it.", "That a large vessel holds more liquid, since the relation has no inventory in it.", "That a large vessel is more likely to be insulated, since the relation has no insulation thickness in it."]'::jsonb, 1, 'The fire''s whole geometry lives inside one published constant and one published power, which is exactly why this is a screening calculation.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 9, 'What does the validation oracle actually check about the two constants and the exponent?', '["That the two constants stand in the published ratio to each other at every wetted area.", "That the duty per ft2 falls monotonically across the whole area sweep.", "That the USC pair follows from the published SI pair with the exponent carried through the unit conversion.", "That the duty the engine returns matches a pool fire model derived independently in SI."]'::jsonb, 2, 'It checks the unit packaging and it would not notice wrong pool fire physics behind the published pair, because it never leaves that pair.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 10, 'What follows, in this course, from the fact that the constants and the exponent are held for literature?', '["Nothing graded in this course reads a fire duty or a fire relief load.", "Nothing in this course teaches the fire case, which is deferred to the tier above.", "The fire duty is taught without any figures, since a held item cannot be printed.", "The published fire rows are excluded from the set, since a held figure cannot be validated."]'::jsonb, 0, 'A held item is taught as a stated value with its reference named and is kept out of the graded surface. It is question material as a limit rather than as an answer.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 11, 'On the teaching vessel at an environment factor of 1.000000, what does the drainage answer do to the duty?', '["It moves it between 4434115.2612 and 1330234.5784 Btu/hr.", "It moves it between 4434115.2612 and 6796981.4402 Btu/hr.", "It leaves the duty alone and moves the relief load instead, from 34641.5255 lb/hr upward.", "It moves it between 4434115.2612 Btu/hr and 7284617.9291 Btu/hr."]'::jsonb, 3, 'One field, and the duty changes by the factor between the two constants. That answer is a judgment about a plot rather than a measurement, so it belongs in the case record with a reason beside it.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 12, 'Where the honest position is that nobody knows whether the plot drains, what goes in the box, and why?', '["True, because the smaller duty is the one the published rows are validated against.", "False, because the duty that follows is the larger one and a valve sized against it passes the smaller case too.", "False, because the engine refuses a drainage answer it cannot check.", "Either, because the environment factor can be lowered to compensate for whichever answer is used."]'::jsonb, 1, 'A boolean carries no uncertainty, so there is no partial credit for a bund that drains a small spill and is overwhelmed by a large one. The answer has to be defensible on its own.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 13, 'How does the published fire set show that the two constants have not been transposed?', '["It carries one geometry at both drainage answers.", "It carries four rows at four wetted areas.", "It carries the ratio between the two constants as a column of its own.", "It carries a duty per ft2 column on every row."]'::jsonb, 0, 'The two rows at 628.3000 ft2 differ only in the drainage answer, so a module that used the wrong constant on either branch could not reproduce both.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 14, 'The three published relief-load rows all sit at a relative difference of 5.876e-10. What does the sameness of that figure say?', '["That the three cases were run at the same duty and differ only in their latent heats.", "That the load route converged to the same residual on all three, which is what the rows exist to show.", "That the published loads were recomputed from the engine figures, so the rows cannot disagree.", "A constant rounded on its way into print, which every row then inherits equally."]'::jsonb, 3, 'A case-dependent error moves from row to row. One that does not move is arithmetic in the conversion the route performs, which is the same conversion every time.'),
  ('relief', 'intermediate', 'module', 'm03-the-pool-fire-duty', 15, 'One published load row reads 99999.9999 lb/hr against an engine load of 100000.0000 lb/hr. What is that?', '["A genuine disagreement at the fourth decimal, which is why the row was kept in the set.", "The engine rounding up where the published figure rounds down, which no tolerance can reconcile.", "One number written two ways, so reporting it as a disagreement reports a print format.", "The one row in the set where the load route is outside the range the oracle can reach."]'::jsonb, 2, 'The row runs a duty of 10000000.0000 Btu/hr against a latent heat of 100.000000 Btu/lb, which is a division with a clean answer. What differs is how each side chose to print it.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 1, 'The fire case runs as a chain. In what order do its steps have to be taken?', '["Relief load, then wetted area, then duty, then required area, then orifice.", "Wetted area, then duty, then relief load, then required area, then orifice.", "Wetted area, then relief load, then duty, then required area, then orifice.", "Duty, then wetted area, then relief load, then orifice, then required area."]'::jsonb, 1, 'The duty needs the area, the load needs the duty, the required area needs the load and the relieving pressure together, and the letter needs the required area. Nothing in that sequence can be rearranged.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 2, 'Six of the seven rows in the teaching chain name the route that produced them. Which row names none, and why?', '["The margin of 1.164566, because the selection route returns the letter and the caller forms the margin.", "The relief load of 34641.5255 lb/hr, because no route in the module computes a load.", "The wetted area of 683.6960 ft2, because geometry is the caller''s own work.", "The relieving pressure of 347.450000 psia, because it is arithmetic outside any engine call."]'::jsonb, 3, 'It is built from the set pressure, the overpressure fraction and the atmospheric constant, and the sizing route is handed the result. It is also the row where the unit changes from psig to psia.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 3, 'The teaching case reaches a required area of 1.578271 in2. What does the selection return?', '["Orifice K at 1.838000 in2, with a margin of 1.164566.", "Orifice K at 1.838000 in2, with a margin of 1.354759.", "Orifice J at 1.287000 in2, with a margin of 1.164566.", "Orifice L at 2.853000 in2, with a margin of 1.282951."]'::jsonb, 0, 'The smallest standard orifice at or above the required area is the one returned, and the margin says how much of that standard size the case is not using.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 4, 'The margin printed beside an orifice letter is a ratio. Of what to what?', '["The required area, to the standard orifice area it was selected into.", "The standard orifice area, to the area of the next orifice down the ladder.", "The standard orifice area, to the required area it was selected for.", "The required area, to the required area the same case would need at the next overpressure allowance."]'::jsonb, 2, 'A margin close to one means the case sits just inside its letter and a small increase in load pushes it to the next orifice. A large margin means the letter has room, and neither is a fault.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 5, 'The teaching case states 21.000000 percent overpressure. Run the same case at 10.000000 percent and what happens?', '["The relieving pressure falls to 317.200000 psia, the required area falls to 1.128544 in2, and the letter moves to J.", "The relieving pressure rises to 476.700000 psia instead, the required area falls to 1.578271 in2, and the letter stays K.", "The relieving pressure falls to 317.200000 psia, the required area rises to 1.728783 in2, and the letter moves to L.", "The relieving pressure falls to 317.200000 psia, the required area rises to 1.728783 in2, and the letter stays K."]'::jsonb, 3, 'A change in the required area only shows as a change in the answer when it crosses an orifice boundary, and this one does not.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 6, 'Why does a larger overpressure allowance make the required area smaller?', '["Because a critical nozzle passes more mass per unit area as the upstream pressure rises.", "Because the allowance is applied to the relief load before the sizing route sees it.", "Because a larger allowance lowers the back pressure ratio and moves the case into critical flow.", "Because the allowance enters the area expression as the discharge coefficient does."]'::jsonb, 0, 'The allowance raises the relieving pressure, and the same load through a higher pressure needs less flow area. That is the part most readers guess backwards, because an allowance sounds like a concession that ought to cost something.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 7, 'Which figures in the teaching chain are identical at both overpressure allowances?', '["The relieving pressure, the required area and the margin.", "The relief load, the required area and the orifice letter.", "The wetted area, the pool fire duty and the relief load.", "Only the wetted area, since the duty carries the pressure through the environment factor."]'::jsonb, 2, 'None of those three takes a pressure, so the allowance enters at the sizing step and only there. An input moves only the steps below where it enters.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 8, 'Answer the drainage question false on the teaching case and hold everything else. What does the chain give?', '["A duty of 7284617.9291 Btu/hr, a load of 56911.0776 lb/hr, a required area of 2.592873 in2 and orifice M.", "A duty of 7284617.9291 Btu/hr, a load of 56911.0776 lb/hr, a required area of 2.592873 in2 and orifice L.", "A duty of 6796981.4402 Btu/hr, a load of 56911.0776 lb/hr and orifice L.", "A wetted area of 1031.7419 ft2, a duty of 7284617.9291 Btu/hr and orifice L."]'::jsonb, 1, 'The wetted area is untouched at 683.6960 ft2, because the drainage answer is not geometry. One word moves the case one letter up the ladder.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 9, 'Drop the environment factor to 0.3 on the teaching case. Which letter does the chain reach, and out of what duty?', '["Orifice F, out of the same 1330234.5784 Btu/hr.", "Orifice G, out of 1336211.5771 Btu/hr instead.", "Orifice J, at 2217057.6306 Btu/hr.", "Orifice G, out of 1330234.5784 Btu/hr."]'::jsonb, 3, 'That factor multiplies the heat rate directly and carries through to 10392.4576 lb/hr and then to 0.473481 in2. It is a judgment that leaves no trace in the figure it produces.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 10, 'Trim the level to 2.0 ft, then instead raise it to 8.0 ft. What do the two changes give?', '["454.1771 ft2 leading to orifice J, and 1031.7419 ft2 leading to orifice L.", "454.1771 ft2 leading to orifice G, and 1031.7419 ft2 leading to orifice L.", "454.1771 ft2 leading to orifice J, and 1031.7419 ft2 leading to orifice M.", "158.3363 ft2 leading to orifice J, and 1031.7419 ft2 leading to orifice L."]'::jsonb, 0, 'Those are the two rows where the wetted area itself moves, and the change carries all the way through the duty, the load and the required area to a different letter each time.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 11, 'The required area row of the teaching chain reports a branch. Which, and what does reporting it buy?', '["Critical, so a reader can see that the back pressure was never stated.", "Critical, so a reader can see which of the two gas expressions produced the area.", "Subcritical, so a reader can see that the relieving pressure sits below the critical ratio.", "Neither, because the fire case uses its own expression rather than the gas route."]'::jsonb, 1, 'The branch is reported rather than assumed. Taking that branch apart is the Associate tier''s work and this tier does not repeat it.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 12, 'Look the latent heat up at the wrong pressure and 90 Btu/lb goes in instead of the stated figure. What comes back?', '["Orifice L, reached through 49267.9473 lb/hr, with a near-critical warning attached to it.", "Orifice K, since 4434115.2612 Btu/hr and 34641.5255 lb/hr are both unmoved by a property.", "Orifice L, reached through 49267.9473 lb/hr with the heat rate unmoved.", "Orifice K, reached through 44341.1526 lb/hr, which is the sweep row at 100.000000 Btu/lb."]'::jsonb, 2, 'The required area becomes 2.244651 in2. A latent heat enters after the heat rate is finished, so one property lookup moves the letter and nothing fires on either case.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 13, 'Read the teaching vessel standing up rather than lying down. What does the whole chain give?', '["158.3363 ft2 of wetted shell, ending on orifice G.", "226.1947 ft2 of wetted shell, ending on orifice G.", "158.3363 ft2 of wetted shell, ending on orifice F.", "683.6960 ft2 of wetted shell, ending on orifice K, since the steel and the level are unchanged."]'::jsonb, 0, 'The chain runs on through 1336211.5771 Btu/hr, then 10439.1529 lb/hr, then 0.475609 in2. One word in one field, and the case lands three rungs of the ladder from where it lands lying down.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 14, 'Two of the changes in the sweep are a single word each. Which, and which way does each move the letter?', '["Drainage false takes K to G, and standing up takes K to L.", "Drainage false takes K to L, and standing up takes K to J.", "Drainage false takes K to M, and standing up takes K to G.", "Drainage answered false takes K to L, and reading the vessel standing up takes K to G."]'::jsonb, 3, 'Neither is a calculation error. Both are a description of the plant somebody entered, and the answer that follows is correct for the plant described.'),
  ('relief', 'intermediate', 'module', 'm04-the-fire-case-end-to-end', 15, 'Why is the sensitivity of the letter not the sensitivity of the required area?', '["Because the selection rounds the required area to the nearest listed area rather than the next one above.", "Because the margin is applied to the required area before the selection reads it.", "Because the ladder is a published table of discrete areas and a required area lands wherever it lands.", "Because the letters are evenly spaced in area, so a fixed change in area always moves the same number of letters."]'::jsonb, 2, 'Two quite different required areas can share a letter, as the two overpressure allowances do, and two similar ones can fall either side of a boundary. Where a case sits inside its letter is what the margin tells you.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 1, 'What does a horizontal knockout drum have to satisfy, in one sentence?', '["The vapour velocity stays below the settling velocity of the design droplet.", "The vapour space holds at least as much volume as the liquid the header can deliver.", "The vapour takes longer to cross the drum than a droplet takes to fall out of it.", "The droplet falls further than the drum diameter over the length of the drum."]'::jsonb, 2, 'Two times are compared: a transit time along the length and a fall time down through the vapour space. At a candidate diameter the engine returns the length that comparison demands.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 2, 'What is the holdup input to the drum route a fraction of?', '["The diameter, since it is the liquid level as a level instrument reads it.", "The circular cross-section, since it is the liquid area fraction of the drum.", "The drum volume, since it is the inventory the drum is allowed to keep.", "The vapour depth, since it is what the droplet has to fall through."]'::jsonb, 0, 'Everything else follows from that convention. The vapour cross-section is the exact circular segment above the level, and the distance a droplet falls is the vapour depth.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 3, 'Which four of the returned fields exist so a reader can see what the fraction they typed was taken to mean?', '["The vapour velocity, the required length, the L over D and the note, which are the four that restate the level fraction.", "The liquid depth, the vapour area, the required length and the L over D.", "The segment area fraction, the vapour velocity, the fall distance and the note.", "The liquid depth, the segment area fraction, the vapour area and the fall distance."]'::jsonb, 3, 'Those four say what the route did with the level fraction before it reached a length. The convention is visible rather than inferred.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 4, 'A circle is filled to a depth fraction of 0.100000. What fraction of its area is liquid?', '["0.100000, since the two agree wherever the segment is small.", "0.052044, so the area fraction sits well below the depth fraction there.", "0.947956, which is the vapour area fraction at that depth.", "0.195501, which is the area fraction at a depth fraction of 0.250000."]'::jsonb, 1, 'Read the table at 0.750000 as well, where the liquid area fraction is 0.804499. The two readings get a long way apart in both directions.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 5, 'Between an empty circle and a full one, at what depth fraction does the area fraction equal the depth fraction?', '["At 0.250000 and again at 0.750000, where the two tables cross.", "At every depth, since the area fraction is the depth fraction of a circle.", "At 0.500000, where the area fraction is 0.500000000000.", "At 0.100000, where the area fraction is 0.052044."]'::jsonb, 2, 'The segment area fraction at half depth is 0.500000000000. A drum sized by typing an area fraction into a level fraction field is sized for the wrong vapour space, and the answer comes back looking entirely normal.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 6, 'This academy answers the settling question three times. Which answer does this course own?', '["The API 521 drag-coefficient method, iterated against the Reynolds number.", "The Souders-Brown allowable velocity, with its K value.", "The Turner and Coleman criteria for a droplet in a rising gas.", "The transit time against the fall time in a horizontal drum."]'::jsonb, 0, 'Gas well loading owns drag against weight with Turner and Coleman, and Separation and Slug Catching owns Souders-Brown and the critique of borrowing it. This course re-derives neither.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 7, 'The settling group comes back as 0.000140743657 at 100 micron, at 200 micron, and again at 0.02 cp. What do those three equalities establish?', '["That the settling velocity is independent of the droplet size and of the viscosity.", "That the group carries neither the droplet size nor the viscosity, so what is left is the coefficient, gravity and the unit conversion.", "That the drag coefficient is constant across that range, which is why the group does not move.", "That the group is the balance itself, so any input reproduces it and the equality proves nothing."]'::jsonb, 1, 'The velocity itself moves a great deal across those cases. It is the group formed from the returned pair that does not, which is what separates the size conversion from the rest of the balance.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 8, 'Divide that group by standard gravity in ft/s2 and 1.333333333333 is left. What is that figure?', '["The coefficient of the balance, times the foot per micron.", "The drag coefficient at the droplet size the group was measured at.", "The ratio of the group at 100 micron to the group at 200 micron.", "The coefficient of the balance squared, times the foot per micron."]'::jsonb, 3, 'The balance is a coefficient times the square root of a group, so squaring the velocity squares the coefficient. What remains after gravity is taken out is that square and the unit conversion.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 9, 'The first two rows of the droplet sweep both return a drag coefficient of 240.000000. What is that?', '["The low-Reynolds cap of the correlation, measured at 240.000000000000.", "The drag coefficient of a sphere in creeping flow at those Reynolds numbers.", "The largest drag coefficient the iteration is allowed to try before it gives up.", "The value the correlation returns wherever it has not converged."]'::jsonb, 0, 'The Reynolds number just inside that cap is 0.104182271364. Below there the fit would keep climbing and the cap holds it, so the balance becomes an explicit expression and the loop finishes quickly.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 10, 'The dropout route returns a velocity of 4.005010 ft/s together with a drag coefficient of 1.026414. Why are the two returned as a pair?', '["Because the drag coefficient is the input the caller has to supply on the next call.", "Because the velocity alone cannot be converted out of SI without the coefficient beside it.", "Because the engine recomputes the velocity from the coefficient it is about to return, so the pair can be put back into the balance.", "Because the pair is what the published rows carry, so quoting both is what lets a reader match a row."]'::jsonb, 2, 'Quote one without the other and you have quoted half of a solution. That call converged in 19 passes on a residual of 0.000000000000.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 11, 'Read the pass count down the droplet sweep. Where is it smallest and where largest?', '["Smallest at 6000.000000 micron with 9 passes, largest at 5.000000 micron with 3.", "Smallest at 5.000000 micron with 3 passes, largest at 6000.000000 micron with 9.", "Smallest at 400.000000 micron with 19 passes, largest at 60.000000 micron with 44.", "Smallest at 5.000000 micron with 3 passes, largest at 60.000000 micron with 44."]'::jsonb, 3, 'Inside the cap the coefficient is a constant and the loop finishes in three or four passes. Just outside it the fit is steepest in the Reynolds number, so the loop takes many small steps to settle.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 12, 'Walk the diameter from 5.000000 ft to 14.000000 ft at the same duty. What happens to the required length?', '["It falls from 12.648469 ft to 4.517310 ft, while the vapour velocity rises to fill the wider drum.", "It falls from 12.648469 ft to 4.517310 ft, as the vapour velocity falls with it.", "It rises from 4.517310 ft to 12.648469 ft, because a wider drum needs a longer settling path.", "It falls from 12.648469 ft to 4.517310 ft, and the L over D holds at 2.529694 throughout."]'::jsonb, 1, 'A wider drum gives more vapour cross-section, so the vapour crosses it more slowly and less length is needed to give a droplet time to fall. Both columns fall the whole way down.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 13, 'The required length is not monotonic in the holdup. What two effects are fighting?', '["Filling the drum speeds the vapour up, which needs more length, and shortens the fall, which needs less.", "Filling the drum slows the vapour down, which needs less length, and lengthens the fall, which needs more.", "Filling the drum raises the liquid area fraction, which needs more length, and lowers the depth fraction, which needs less.", "Filling the drum raises the dropout velocity, which needs less length, and raises the vapour velocity, which needs more."]'::jsonb, 0, 'Across the whole sweep the required length runs from 6.997154 ft to 44.344927 ft, a spread of 37.347773 ft, while the vapour velocity runs from 3.340002 ft/s to 1973.354184 ft/s.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 14, 'Where are the two edges of the L over D note, and what sits between them?', '["The smaller-drum note ends at 2.000000000000 and the go-wider note starts at 6.000000000000, with a third note between.", "The go-wider note ends at 2.000000000000 and the smaller-drum note starts at 6.000000000000, with silence between.", "The note fires below 0.780770 and above 2.529694, which are the two extremes of the diameter sweep.", "The smaller-drum note ends at 2.000000000000 and the go-wider note starts at 6.000000000000, with silence between."]'::jsonb, 3, 'Both edges are bisected out of behaviour rather than read off constants. The stated drum at 9.000000 ft and a holdup of 0.300000 carries an L over D of 0.780770, so it sits below the lower edge and carries the note.'),
  ('relief', 'intermediate', 'module', 'm05-the-knockout-drum', 15, 'Six distinct holdup fractions appear in the published drum rows. What does that buy the set?', '["It lets the set cover the whole range over which the required length is monotonic.", "It lets the set recover the segment area fraction by fitting six points.", "It lets the set tell a route that reads the holdup from one that ignores it.", "It lets the set check the dropout velocity at six different droplet sizes."]'::jsonb, 2, 'Every one of those rows carries its dropout velocity as an input column, at 1.730000 ft/s on five rows and 2.400000 ft/s on the sixth, so the set exercises the drum geometry with the settling fit out of the way.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A vessel in a pool fire and the drum behind it are read in one session. What do the two halves have in common numerically?', '["The relief load, which the valve is sized on and the drum then passes.", "The vapour rate, which the fire case produces and the drum consumes.", "The relieving pressure, which fixes the required area and the vapour density together.", "Nothing, since no figure appears in both and no figure in one feeds the other."]'::jsonb, 3, 'The valve is sized on the load a fire puts on a vessel. The drum is sized on the vapour the header carries and the droplet the flare tip will not accept.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Which figures in that reading did not come back from a route in this module?', '["The dropout velocity of 4.005010 ft/s, the vapour velocity of 4.467129 ft/s and the required length.", "The vapour density of 0.124385 lb/ft3, the actual vapour rate of 212.481739 acfs and the relieving pressure.", "The wetted area of 683.6960 ft2 and the pool fire duty of 4434115.2612 Btu/hr.", "The required area of 1.578271 in2 and the L over D of 0.780770."]'::jsonb, 1, 'Two are the caller''s conversions from the first module of this tier and the third is arithmetic on a set pressure. Everything else on the screen is an engine return.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Why does this engine not turn a relieving load into a drum rate for you?', '["Because that conversion needs a composition and a temperature at header conditions that nothing has given it.", "Because the two halves belong to different tiers of this course.", "Because the drum route refuses any rate that arrives in pounds an hour.", "Because a relieving load is a mass flow and a drum rate is a mass flow at different conditions."]'::jsonb, 0, 'On a real plant the relieving vapour does travel down the header to the drum. The engine declines to pretend to a link it cannot compute, which is honest rather than convenient.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Four judgments in this tier came from outside the engine. Which row of the reading does the standard-to-actual conversion show up in?', '["The vapour velocity row of the drum half.", "The relief load row of the fire half.", "The vapour rate row of the drum half.", "The dropout velocity row of the drum half."]'::jsonb, 2, 'The other three land on the level typed into the geometry route, on whether this fire case is the one that sizes the valve, and on the properties behind the settling calculation.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Almost every quantity in this tier has a near neighbour that is also a correct number. Which pair is one of them?', '["A required area and the relief load it was computed from.", "A wetted area read lying down and the same level read standing up.", "A vapour velocity in a drum and the required length that follows from it.", "A pool fire duty and the relief load that duty is divided down into."]'::jsonb, 1, 'In every such pair both figures are correct answers to different questions. The others named here are successive steps of one chain rather than two readings of one thing.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A fraction of 0.900000 is handed to the drum as a level and then read as an area fraction instead. What does the course print?', '["21.212138 ft against 17.274356 ft, at a printed ratio of 1.003995.", "14.117118 ft against 13.159863 ft, ratio 0.932192.", "10.481166 ft against 10.346904 ft, ratio 0.987190.", "21.212138 ft against 17.274356 ft, a ratio of 0.814362."]'::jsonb, 3, 'At a fraction of 0.500000 the two conventions give 11.039649 ft either way, which is why a check performed only at half depth proves nothing about the convention.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Two figures in a case record are written in psig and psia. Which is which?', '["The set pressure is psia and the relieving pressure is psig.", "Both are psig, and the atmospheric constant converts the required area instead.", "The set pressure is psig and the relieving pressure is psia.", "Both are psia, since the fire case is sized on absolute pressures throughout."]'::jsonb, 2, 'A set pressure carried into a place wanting absolute is out by one atmosphere in a direction nothing downstream can see.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Why does this tier insist on quoting an engine answer at the precision the engine returned it at?', '["Because a rounded restatement is indistinguishable from a number somebody invented.", "Because the graded fields are marked on the last decimal place rather than on a tolerance.", "Because the engine refuses a figure it did not itself print at that precision.", "Because rounding changes which orifice letter the selection returns."]'::jsonb, 0, 'Rounding partway through a chain also moves everything after it, which is a second reason and the one that costs the most.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Why is an orifice letter on its own an incomplete answer?', '["Because the letter is a published table entry and nothing in this package can derive it.", "Because the selection returns a letter only when the required area is below the largest standard orifice.", "Because the letter changes with the overpressure allowance while the required area does not.", "Because several different required areas map to one letter, so the margin is what says where the case sits inside it."]'::jsonb, 3, 'The selection returns the letter, the standard area behind it, the required area it selected for and the margin between them. Quote all four and the reading can be checked.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'The engine refuses a call rather than answering it. What goes in the answer box?', '["The nearest figure the route would have returned had the input been valid.", "The refusal, because the gap was the point of the question.", "A zero, since a refusal means the quantity does not exist for that case.", "The figure from the equivalent call in the other orientation or convention."]'::jsonb, 1, 'Writing a plausible figure into that gap turns a correct reading into a wrong answer. A warning is different: the load is still the load to quote, with the warning reported beside it.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'What is the fourth and most often skipped step in the order this tier works in?', '["Converting every figure into one consistent unit set.", "Repeating the call at a second diameter to confirm the answer.", "Naming the boundary the answer depends on.", "Recording the orifice letter with the margin beside it."]'::jsonb, 2, 'The first three are the stated conditions with their units, the quantity each question is asking for, and the engine call with its answer at full precision. The fourth is the difference between an answer and a defensible answer.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Which two things does this tier''s walk deliberately exclude?', '["Any route that picks the governing case, and any route that converts a relieving load into a drum rate.", "Any route that computes a relief load, and any route that computes a settling velocity.", "Any route that reads a vessel standing up, and any route that reads a fraction as an area.", "Any route that returns a warning, and any route that returns a note."]'::jsonb, 0, 'Looking for either one wastes time. The comparison between scenarios is yours, and the two halves of the flare system are independent by construction.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A drum question states a settling velocity and also mentions a droplet size elsewhere. Which do you use?', '["The droplet size, since a velocity computed from it is more defensible than one somebody merely typed in.", "Either one, since the settling route reproduces the stated velocity from the droplet size given beside it.", "The droplet size, unless the stated velocity falls inside the band the published rows carry.", "The stated settling velocity, because the drum route takes one as an input and never computes one."]'::jsonb, 3, 'A computed settling velocity rests on the drag correlation, which is held for literature and unchecked by any published case. A stated one rests on a number a reader can see and defend.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Eleven rows arrive on one screen in eight different units, from seven routes and two conversions. What does this tier ask you to do first?', '["Label every figure with the half of the system it belongs to.", "Convert every figure to the unit the graded field will be read in.", "Check each figure against the published row nearest to it.", "Order the figures by the step that produced them."]'::jsonb, 0, 'A required area and a required length are both required, both in the answer, and answers to two unrelated questions. Nothing on the screen groups them.'),
  ('relief', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What arrives at the caller as a note rather than as a refusal or a warning?', '["The ignored back-pressure factor on a subcritical gas case, and the near-critical latent heat.", "An unrecognised orientation, and a level fraction at one.", "The wetted height limit on a pool fire duty, and the L over D judgment on a drum.", "The near-critical latent heat on a relief load, and the drum note below an L over D of 2.000000000000."]'::jsonb, 2, 'A note names a decision the engine has left to the caller on a call that succeeded. The other two kinds of message either replace the answer outright or stand beside one that still holds.'),
  ('relief', 'intermediate', 'final', null, 1, 'Which sentence describes what this engine does with a relieving scenario?', '["It compares the scenarios it is able to compute for itself and sizes against the largest of them.", "It sizes against whatever load it is handed and never decides which scenario governs.", "It refuses any load that does not match the vessel geometry it was given alongside that load.", "It sizes against the load and records the scenario name alongside it."]'::jsonb, 1, 'Every sizing route takes a load as an input. The one route that works out a load of its own starts from geometry rather than from a process description.'),
  ('relief', 'intermediate', 'final', null, 2, 'A relief load is filed without the scenario it was worked out for. What has been lost?', '["The relieving conditions it belongs to, which cannot be recovered from a bare rate afterwards.", "The orifice letter it was found to need, which has to be worked out again from the beginning.", "Nothing that matters, since the sizing routes take a rate and no route anywhere takes a scenario.", "The only thing that would say whether it was a fire rate, a blocked-in rate or a control valve rate."]'::jsonb, 3, 'Six months on, the only way to find out which case the figure came from is to do the work again. Nothing on the screen tells one pounds an hour figure from another.'),
  ('relief', 'intermediate', 'final', null, 3, 'Where in this tier does a standard rate have to become an actual one, and who does it?', '["Before the drum route is called, and the caller does it.", "Inside the drum route, from the header pressure it is given.", "Before the settling route is called, and the caller does it.", "Inside the settling route, from the vapour density it derives."]'::jsonb, 0, 'The route is handed a rate at drum conditions and is never told what pressure the header runs at, so it could not convert anything even if it wanted to.'),
  ('relief', 'intermediate', 'final', null, 4, 'Six facts are stated about the teaching drum. How many of them arrive in a unit the drum route reads?', '["One, the gas rate of 44.000000 MMscfd, which that route reads directly.", "Two, the pressure of 42.000000 psia and the temperature of 160.000000 degF.", "None, which is why two derivations sit between the statement and the call.", "Three, the gas gravity, the liquid density and the vapour viscosity of 0.013500 cp."]'::jsonb, 2, 'The route wants a volumetric rate at drum conditions, a settling velocity, a diameter and a level fraction. The vapour density of 0.124385 lb/ft3 and the rate of 212.481739 acfs are worked out on the way.'),
  ('relief', 'intermediate', 'final', null, 5, 'Why does this course tell a reader not to form a ratio between 44.000000 MMscfd and 212.481739 ft3/s?', '["Because the two figures are quoted at different precisions, so their quotient could only ever be as good as the coarser of them.", "Because such a figure would carry a day, a second, a pressure and a temperature at once, and nothing stands behind it.", "Because the conversion is not linear, so no single ratio describes it.", "Because the engine prints that ratio itself and a hand-formed one would disagree with it."]'::jsonb, 1, 'A day and a second, a standard base and a header pressure are all folded into any quotient of those two. Ask whether a quantity is entitled to be compared before comparing it.'),
  ('relief', 'intermediate', 'final', null, 6, 'Four things in this tier are left to the caller. Which of these is one of them?', '["The segment area fraction behind a stated holdup.", "The branch the gas route takes at the relieving pressure.", "The margin between a required area and the orifice selected for it.", "The liquid density and the vapour viscosity at drum conditions."]'::jsonb, 3, 'This module holds no property tables. The other three are figures the engine works out and returns.'),
  ('relief', 'intermediate', 'final', null, 7, 'Why does this tier start at the geometry rather than at the duty?', '["Because the geometry is the one link in the fire chain that carries nothing published.", "Because the geometry is the only link the validation oracle can reach.", "Because the duty cannot be computed until a latent heat has been looked up.", "Because the geometry is the only link that a level trimmed after the call can still correct."]'::jsonb, 0, 'The duty carries two constants and an exponent, the load carries a latent heat, and the area carries a discharge coefficient. Only the first link can be right beyond argument.'),
  ('relief', 'intermediate', 'final', null, 8, 'A level of 4.200000 ft on a vessel 12.000000 ft across is 0.350000 of its diameter. What are the two readings at that level?', '["683.6960 ft2 and 226.1947 ft2, at a printed ratio of 3.750000.", "500.7394 ft2 and 90.4779 ft2, at a printed ratio of 5.534386.", "683.6960 ft2 and 158.3363 ft2, at a ratio of 4.317999814064.", "1012.7640 ft2 and 294.0531 ft2, at a printed ratio of 3.444154."]'::jsonb, 2, 'The other rows quoted here are real rows of the same sweep at other levels. Reading the wrong row is this tier''s commonest way of producing a correct number that answers nothing.'),
  ('relief', 'intermediate', 'final', null, 9, 'A horizontal vessel is handed a level of ten diameters by mistake. What comes back?', '["A refusal, because a level above the diameter cannot be wetted.", "The area at one diameter, because the level is clamped there.", "An area ten times the area at one diameter.", "The area at one diameter, with a note saying the level was clipped."]'::jsonb, 1, 'That clamp is convenient and it is also a hazard. A units slip that inflated the level by a factor of anything at all is invisible in the answer.'),
  ('relief', 'intermediate', 'final', null, 10, 'Where in the workflow does a level have to be trimmed for the height limit, and why there?', '["After the call, by scaling the area down in the ratio of the two heights involved.", "Inside the wetted area route, which applies the limit once grade has been stated to it.", "At the load step, by scaling the relief load down before the valve is sized against it.", "Before the call, because the duty route takes only an area and there is no second chance downstream."]'::jsonb, 3, 'Establish where grade is, work out what liquid height sits below the reachable limit, type that height, then read the area. Whatever level goes in is the level the whole fire case is built on.'),
  ('relief', 'intermediate', 'final', null, 11, 'The horizontal over vertical ratio column reads 3.750000 at a level fraction of 0.500000 and 3.750000 again at 1.000000. What does the column do between them?', '["It holds at 3.750000 the whole way, since both readings are linear there.", "It rises above 3.750000 and then falls back to it.", "It falls below 3.750000 and then turns and rises back to it.", "It falls steadily to 3.303904 and stays there."]'::jsonb, 2, 'The turn is visible in the printed column. Two equal values at the ends of a range say nothing about what happens inside it.'),
  ('relief', 'intermediate', 'final', null, 12, 'Three of the seven published wetted-area rows are vertical, and each is chosen rather than sampled. What are the three?', '["A tower wetted above its own diameter, one wetted to the height limit, and an empty vessel.", "A tower wetted to half of its own height, one wetted to the height limit, and an empty vessel.", "A tower wetted above its own diameter, one wetted to half of its height, and a full one beside them.", "A tower at each of the three diameters the horizontal rows of the same published set use."]'::jsonb, 0, 'Each is an edge some plausible implementation gets wrong, which is a different thing from three points spread across a range.'),
  ('relief', 'intermediate', 'final', null, 13, 'The oracle behind the wetted-area rows does not evaluate the arc expression the engine uses. What does it do instead?', '["It integrates the segment area by Simpson quadrature in SI.", "It sums a polyline round the real circle and extrapolates.", "It bisects on the force residual until the areas agree.", "It evaluates the same arc expression in higher precision."]'::jsonb, 1, 'An oracle restating the engine''s own algebra proves the arithmetic and nothing about the geometry. The Simpson quadrature belongs to the drum''s vapour area.'),
  ('relief', 'intermediate', 'final', null, 14, 'Which two inputs to the pool fire duty are credits, and how do they differ in kind?', '["The drainage answer and the latent heat, one a boolean and the other a property.", "The environment factor and the exponent, one typed by the caller and the other published.", "The drainage answer and the wetted area, one a boolean and the other geometry.", "The drainage answer, which is a boolean switching the constant, and the environment factor, which multiplies the duty."]'::jsonb, 3, 'Both are credits for a plant provision that makes the fire less severe, and claiming both where neither has been confirmed compounds two optimistic judgments into one duty.'),
  ('relief', 'intermediate', 'final', null, 15, 'What would a set of published fire rows at a single drainage answer fail to catch?', '["A module whose exponent was wrong, since the exponent only shows across two drainage answers.", "A module that applied the environment factor to the load rather than to the duty.", "A module that used the wrong constant on the branch the set never exercises.", "A module whose duty was right and whose unit packaging was wrong."]'::jsonb, 2, 'The two rows at 628.3000 ft2 differ only in that answer, which is what makes the pair able to fail.'),
  ('relief', 'intermediate', 'final', null, 16, 'The duty per ft2 at 100.0000 ft2 is 9166.8325 Btu/hr and at 1000.0000 ft2 it is 6056.4662 Btu/hr. What produced that fall?', '["The exponent of 0.820000000000 sitting below one.", "The drainage constant switching between the two rows of the sweep.", "The environment factor falling as the area rises through the sweep.", "The wetted height limit truncating the larger of the two areas."]'::jsonb, 0, 'Those two areas are also the pair the exponent was measured from, by the log ratio of their duties over the log ratio of the areas.'),
  ('relief', 'intermediate', 'final', null, 17, 'A reader concludes from the duty sweep that one very large vessel and several small ones with the same total shell are the same fire problem. What is wrong with that?', '["Nothing, since the relation is a function of total wetted area alone.", "Duty per square foot falls with size, so the large vessel absorbs less per square foot than the small ones do.", "Duty per square foot rises with size, so the large vessel absorbs more per square foot.", "The relation cannot be applied to more than one vessel at a time, so neither of the two figures being compared exists at all."]'::jsonb, 1, 'The per-square-foot column is printed for exactly this reading. The exponent packages a fire''s geometry into one number and that is the consequence of it.'),
  ('relief', 'intermediate', 'final', null, 18, 'Somebody claims the oracle behind the pool fire duty validates the pool fire model. What is the honest correction?', '["It checks the duty against an independent radiation model derived in SI.", "It checks the exponent by fitting the duty sweep, which is a genuinely separate derivation.", "It checks nothing at all, which is why the constants are held for literature.", "It checks the unit packaging between the published USC pair and the published SI pair, and never leaves that pair."]'::jsonb, 3, 'A check that cannot reach the model has to say so. This one does, and the practical consequence is that nothing graded in this course reads a fire duty or a fire relief load.'),
  ('relief', 'intermediate', 'final', null, 19, 'Which figures move and which stay still when the latent heat is walked at a fixed duty?', '["The load moves and the duty does not, because the latent heat enters after the duty is finished.", "Both move, because the latent heat is an input to the duty and to the load.", "The duty moves and the load does not, because the load is fixed by the wetted area the chain started from.", "Neither of them moves until the latent heat crosses 50.000000000000 Btu/lb, which is where the warning fires."]'::jsonb, 0, 'A smaller latent heat gives a larger load, and the growth accelerates as the divisor shrinks. At 300.000000 Btu/lb the load is 14780.3842 lb/hr and at 30.000000 Btu/lb it is 147803.8420 lb/hr.'),
  ('relief', 'intermediate', 'final', null, 20, 'Why does the engine warn rather than refuse below a latent heat of 50.000000000000 Btu/lb?', '["Because the warning fires on a bisected edge and a refusal would need an exact one.", "Because the load is still exact there and only the duty has become questionable.", "Because the load is still the best available screening estimate and near-critical relief has to be sized somehow.", "Because a refusal would leave the fire chain with no load, and the chain has no other source."]'::jsonb, 2, 'Near-critical relief has to be sized somehow, and the standards acknowledge the method is breaking down there rather than forbidding it. What the warning adds is that the relation is outside the range where it can be trusted alone.'),
  ('relief', 'intermediate', 'final', null, 21, 'Thirteen figures are stated for the teaching fire case. What does that count say about the calculation?', '["That a fire case needs more inputs than any other route in the module.", "That a fire case is thirteen decisions followed by arithmetic.", "That four of the thirteen describe steel and the rest are properties.", "That thirteen is the number of fields the studio refuses to default."]'::jsonb, 1, 'Four describe steel, two are credits, one is a property, and six describe the valve''s pressures and the relieving gas. Everything after them is arithmetic the engine does for itself.'),
  ('relief', 'intermediate', 'final', null, 22, 'The relieving pressure of 347.450000 psia is built from three things. Which three?', '["The set pressure of 275.000000 psig, the overpressure of 21.000000 percent, and the back pressure at the valve outlet.", "The set pressure of 275.000000 psig, the relief load of 34641.5255 lb/hr, and the measured atmospheric constant.", "The set pressure of 275.000000 psig, the overpressure of 10.000000 percent, and the measured atmospheric constant.", "The set pressure of 275.000000 psig, the overpressure of 21.000000 percent, and the measured atmospheric constant."]'::jsonb, 3, 'The same three questions recover that atmospheric constant three different ways, which is how this course knows the whole module shares one atmosphere.'),
  ('relief', 'intermediate', 'final', null, 23, 'A fire allowance is typed into a process case by mistake. Which way is the valve wrong?', '["Too small, because the higher relieving pressure needs less flow area.", "Too large, because the higher relieving pressure needs more flow area.", "Too small, because the allowance is applied to the relief load as well.", "Neither, because the allowance and the load cancel in the area expression."]'::jsonb, 0, 'The number looks entirely ordinary on the screen. A bigger allowance sounds like a concession that ought to cost something and in the sizing arithmetic it buys area back.'),
  ('relief', 'intermediate', 'final', null, 24, 'Which of these changes leaves the wetted area of the teaching case exactly where it was?', '["Trimming the liquid level to 2.0 ft before the call.", "Reading the same vessel standing up instead.", "Answering the drainage question false.", "Raising the liquid level to 8.0 ft instead."]'::jsonb, 2, 'The drainage answer, the environment factor and the latent heat all leave the wetted area at 683.6960 ft2, because none of them is geometry. An input moves only the steps below where it enters.'),
  ('relief', 'intermediate', 'final', null, 25, 'Two changes in the one-input sweep land the case on orifice G. Which two?', '["An environment factor of 0.3, and trimming the level to 2.0 ft.", "An environment factor of 0.3, and reading the vessel standing up.", "Reading the vessel standing up, and a latent heat of 90 Btu/lb.", "Trimming the level to 2.0 ft, and answering the drainage question false."]'::jsonb, 1, 'They reach it by different routes. One leaves the wetted area at 683.6960 ft2 and cuts the duty, and the other cuts the wetted area to 158.3363 ft2 and lets the chain follow.'),
  ('relief', 'intermediate', 'final', null, 26, 'The stated case and the case at a latent heat of 90 Btu/lb both come back without a warning. Why is that worth saying?', '["Because a warning on the relief load route only fires when the duty beside it is also out of range.", "Because the warning for that case was already spent on the drainage answer further up the chain.", "Because both of those latent heats sit below the edge, which is where the engine stops warning at all.", "Because most of the risk on that input sits far above the edge, where nothing fires at all."]'::jsonb, 3, 'A latent heat looked up at the wrong pressure is the commonest way that step goes wrong, and nothing in the return can detect it.'),
  ('relief', 'intermediate', 'final', null, 27, 'At 21.000000 percent the teaching case needs 1.578271 in2 and at 10.000000 percent it needs 1.728783 in2, and both buy the same valve. What does that show?', '["That a movement in the required area is invisible in the answer until it crosses a boundary.", "That the selection rounds a required area to the nearest listed area rather than the next one up.", "That the overpressure allowance is applied after the letter has already been chosen.", "That the two areas fall inside the margin the selection allows before it moves a letter."]'::jsonb, 0, 'Judging how robust a selection is means knowing where the required area sits inside its letter, and the figure that says so is printed beside it.'),
  ('relief', 'intermediate', 'final', null, 28, 'A drum is sized by typing an area fraction into the field that wants a level fraction. What does the answer look like?', '["It refuses, because the two conventions disagree above half depth.", "It carries a note, because the route returns the segment area fraction it derived.", "Entirely normal, because both are fractions between zero and one and the route cannot tell them apart.", "It is unchanged, because the route converts one convention into the other."]'::jsonb, 2, 'At a fraction of 0.100000 the level reading gives 10.481166 ft and the area reading gives 10.346904 ft. Neither is flagged and only one answers the question asked.'),
  ('relief', 'intermediate', 'final', null, 29, 'What does the drum route do with the dropout velocity, and why does this course state one rather than compute it?', '["It takes one as an input, and a computed one would rest on a fit no published case can check.", "It takes one as an input, and a computed one would need a droplet size the exercise does not give.", "It computes one from the droplet size, and the course states one only to save arithmetic.", "It computes one from the vapour density, and the course states one to keep the units consistent."]'::jsonb, 0, 'A computed velocity would silently inherit an empirical fit that the validation oracle shares with the engine on purpose. A stated one rests on a number a reader can see and defend.'),
  ('relief', 'intermediate', 'final', null, 30, 'Two engineers size one drum, make no arithmetic error, and produce different lengths. What is the likeliest reason?', '["They used different standard bases for the vapour rate, which the drum route has no way of detecting.", "One of them read the L over D note the engine returned and went wider on the strength of it.", "They used different drag correlations, since the empirical fit arrives as an input to the settling route.", "They chose different design droplets, and the settling velocity is sensitive to that choice."]'::jsonb, 3, 'The droplet size is a design decision rather than a measurement, and a flare drum is usually sized in the part of the curve where the drag coefficient moves fastest. The choice belongs in the case record beside the answer.'),
  ('relief', 'intermediate', 'final', null, 31, 'Why does the loop converge in 3 passes at 5.000000 micron and take 44 at 60.000000 micron?', '["Because the smaller droplet has a lower Reynolds number, and the loop converges faster at low Reynolds numbers generally.", "Because the smaller droplet sits inside the drag cap, where the coefficient is a constant and the balance is explicit.", "Because the larger droplet has not converged, which is what a high pass count reports.", "Because the smaller droplet is below the size the correlation covers, so the loop exits at once."]'::jsonb, 1, 'Every row in that sweep converged, including the slowest. A slow convergence is a signal about where on the curve the case sits rather than a sign of trouble.'),
  ('relief', 'intermediate', 'final', null, 32, 'The drag cap is measured at 240.000000000000 and the Reynolds number just inside it at 0.104182271364. Which figure answers which question?', '["The first is the largest Reynolds number in the sweep, and the second is the coefficient there.", "The first is where the coefficient stops moving, and the second is the residual the loop stops at.", "The first is where the coefficient stops moving, and the second is the Reynolds number at that edge.", "The first is the coefficient at the smallest droplet, and the second is the velocity it gives."]'::jsonb, 2, 'Both were measured out of the engine''s own behaviour. Below that edge the fit would keep climbing and the cap holds it.'),
  ('relief', 'intermediate', 'final', null, 33, 'Walking the diameter and walking the holdup behave differently. How?', '["The diameter is a clean lever and the holdup is not, because the length turns inside the holdup range.", "The holdup is a clean lever and the diameter is not, because the length turns inside the diameter range.", "Both are clean levers, since both columns fall the whole way down their sweeps.", "Neither is a lever, since the required length is set by the dropout velocity alone."]'::jsonb, 0, 'Push the diameter one way and both the vapour velocity and the required length follow. Fill the drum and two effects move against each other.'),
  ('relief', 'intermediate', 'final', null, 34, 'Across the whole holdup range the required length runs from 6.997154 ft to 44.344927 ft. What is the spread, and what does printing it do?', '["37.347773 ft, and printing it licenses any other quotient a reader wants from the same table.", "6.997154 ft, since the spread of a non-monotonic column is its smallest value.", "44.344927 ft, since the spread is measured from an empty drum.", "37.347773 ft, and printing it means the reader does not have to form a comparison the engine never made."]'::jsonb, 3, 'The spread is computed for the reader, so nobody has to divide one row by another to learn what the input is worth. A quotient assembled off the page is a figure this engine never produced.'),
  ('relief', 'intermediate', 'final', null, 35, 'The stated teaching drum carries the note about a smaller drum. What does that mean about it?', '["It does not work, and a narrower drum is needed to meet the criterion.", "It works, and a narrower drum would also work for less steel.", "It works, and the note is a refusal the caller is allowed to overrule.", "It cannot be judged, since the note fires at both edges of the band."]'::jsonb, 1, 'Its L over D of 0.780770 sits below the lower edge of 2.000000000000. Outside the band the engine offers a judgment rather than a refusal, because a long thin drum or a wide flat one can be exactly what a plot allows.'),
  ('relief', 'intermediate', 'final', null, 36, 'A required area of 1.578271 in2 and a required length of 7.026927 ft appear on one screen. What is the relation between them?', '["The length is the drum the valve of that area discharges into.", "The area sizes the valve and the length sizes the drum that passes the same vapour.", "None, because they answer two unrelated questions about two pieces of equipment.", "The length follows from the area through the vapour rate at header conditions."]'::jsonb, 2, 'Both are required, both are in the answer, and nothing on the screen groups them. Labelling every figure with the half it belongs to is what stops them being mixed.'),
  ('relief', 'intermediate', 'final', null, 37, 'The exact circular segment turns up twice in this tier. Where, and what does it decide each time?', '["In the wetted area, where it sets what the fire reaches, and in the drum, where it sets the vapour space and the fall distance.", "In the wetted area, where it sets what the fire reaches, and in the settling balance, where it sets the drag coefficient.", "In the drum, where it sets the vapour space, and in the orifice ladder, where it sets the selection boundary.", "In the wetted area and in the pool fire duty, which is why the exponent applies to a segment area."]'::jsonb, 0, 'One geometry, two questions. In the drum the same segment decides both how much vapour space there is and how far a droplet has to fall.'),
  ('relief', 'intermediate', 'final', null, 38, 'Half full on a vessel and half depth in a drum have something in common. What?', '["Both are the level at which the engine switches between two branches.", "Both are the only levels the published sets exercise.", "Both are levels at which the engine attaches a note to its answer.", "Both are a point where two different expressions agree, so a check made only there proves nothing."]'::jsonb, 3, 'At 6.000000 ft the segment area and half the lateral surface agree to a ratio of 1.000000000000. At a fraction of 0.500000 the level and area conventions give 11.039649 ft either way. An empty drum agrees with itself as well, so neither agreement says anything about any other level.'),
  ('relief', 'intermediate', 'final', null, 39, 'One word changes the letter in the fire chain and one convention changes the length in the drum. Which pair is it?', '["The drainage answer, and whether a stated velocity is a dropout or a vapour velocity.", "The orientation of the vessel, and whether a stated fraction is a level or an area.", "The orientation of the vessel, and whether a stated rate is standard or actual.", "The environment factor, and whether a stated fraction is a level or an area."]'::jsonb, 1, 'Both are a description that arrives as a number and leaves no trace in the answer. Neither is a calculation error and both produce a figure that is correct for something else.'),
  ('relief', 'intermediate', 'final', null, 40, 'Two of this tier''s boundaries are places where the engine is missing one piece of information. Which two, and what is missing?', '["The height truncation, which needs the plot elevation, and the rate conversion, which needs the header conditions.", "The height truncation, which needs the latent heat, and the rate conversion, which needs the droplet size.", "The governing case, which needs the process description, and the height truncation, which needs the orientation.", "The rate conversion, which needs the standard base, and the fluid properties, which need the relieving pressure."]'::jsonb, 0, 'A vessel on a plinth and one in a bunded pit present different amounts of shell within reach, and a header at one pressure carries a different volume from the same standard rate. The module states both gaps.'),
  ('relief', 'intermediate', 'final', null, 41, 'What does this tier say a learner should be able to do at the end of it?', '["Say which of the two gas branches a case will take before calling the route.", "Say what a stated fraction is a fraction of.", "Say which relieving scenario governs a given vessel.", "Say how a required area changes as a step size is refined."]'::jsonb, 1, 'A holdup is a fraction of a diameter, an area fraction is a fraction of a circle, and a level is a fraction of nothing at all until somebody says where grade is.'),
  ('relief', 'intermediate', 'final', null, 42, 'A relief load in lb/hr and a vapour rate in acfs are the two rates in this tier. What is the relation between them?', '["The load converts to the rate through the vapour density the drum route derives.", "The load converts to the rate through the relieving pressure and the molecular weight.", "There is none here, since the engine is handed the drum rate rather than deriving it from any relief case.", "They are the same quantity in two unit systems, which is why only one of them is stated."]'::jsonb, 2, 'Connecting the two on a real plant means a composition and a temperature at header conditions that nothing has given this engine.');
